--  Bootcamp Integración — Datos dummy de clientes bancarios
-- =============================================================


-- Vista útil para consultas de prueba
CREATE OR REPLACE VIEW v_resumen_clientes AS
SELECT
    tipo_cuenta,
    COUNT(*)                        AS total_clientes,
    ROUND(AVG(saldo), 2)            AS saldo_promedio,
    ROUND(SUM(saldo), 2)            AS saldo_total,
    COUNT(*) FILTER (WHERE activo)  AS clientes_activos
FROM clientes
GROUP BY tipo_cuenta
ORDER BY tipo_cuenta;
